    lines.push('🗓️ Tahun ajaran terdekat: '+nextIntake(row)+(row[15] ? '' : ' (jadwal umum semester; cek halaman resmi)'));
    lines.push('🔑 Kode CRICOS program: '+row[1].join(' / ')+'\n    Kode CRICOS kampus: '+row[11]);
    lines.push('✅ Kenapa cocok: '+whyText(c, n, a));
    var cl = careerLines(row, a.jenjang || 's2'); if(cl.length) lines.push('🚀 *Karier ke depan* yang bisa kamu raih dari gelar ini\n'+cl.join('\n')+'\nℹ️ Catatan karier: dipetakan otomatis dari nama program ke klasifikasi pekerjaan resmi Australia. Ini gambaran jenjang karier, bukan jaminan pekerjaan. Angka gaji adalah median di Australia, bukan di Indonesia.');
    if(cn) lines.push('🏙️ Sesuai preferensimu: '+cn.tags.map(function(t){ return CITY_NOTE[t]; }).join(' dan ')+' ('+cn.city+')');
    lines.push('🗣️ Bahasa: '+langLine(a,row));
    lines.push('🎓 *Peluang beasiswa*\n'+schLines(a,u).join('\n'));
